#: wallet_id / rotation_id / signing_request_id 允许的字符（同时杜绝路径穿越）
_SAFE_ID = re.compile(r"^[A-Za-z0-9_-]{1,128}$")

#: share_id 允许的字符：轮换份额 id 为 <rotation_id>-share-N，最长 128+8
_SAFE_SHARE_ID = re.compile(r"^[A-Za-z0-9_-]{1,136}$")


def _check_id(kind: str, value: str) -> None:
    if not isinstance(value, str) or not _SAFE_ID.match(value):
        raise ValueError(f"invalid {kind}: {value!r}")


def _check_share_id(value: str) -> None:
    if not isinstance(value, str) or not _SAFE_SHARE_ID.match(value):
        raise ValueError(f"invalid share_id: {value!r}")


def _is_replacement_share_id(value: object) -> bool:
    """会话参与者替换份额的 id 形态：``<replacement_id>-share``。

    钱包/轮换份额（share-1、share-2、<rotation_id>-share-N）从不以
    ``-share`` 结尾，故 shares/<wallet_id>/ 下以 ``-share`` 结尾的正式
    份额文件只会来自会话参与者替换；轮换现场对账对它们豁免（其有无与
    自洽性由签名会话恢复按 session_participant_replaced 事件对账）。
    """
    return isinstance(value, str) and value.endswith("-share")


def _is_plain_int(value: object) -> bool:
    """真·整数：bool 是 int 子类，必须排除（余额/版本/delta 均不接受布尔）。"""
    return isinstance(value, int) and not isinstance(value, bool)


def _valid_safe_id(value: object) -> bool:
    return isinstance(value, str) and bool(_SAFE_ID.match(value))


def parse_utc_iso(value: object) -> Optional[datetime]:
    """严格解析 UTC 时间戳字符串。

    仅接受带时区信息的 ISO-8601 字符串（服务自身始终写 ``...Z``）；
    朴素时间（无 tz）、非字符串、不可解析或偏移非零固定值之外的内容
    一律返回 None。返回统一到 UTC 的 aware datetime，便于严格比较。
    """
    if not isinstance(value, str) or not value:
        return None
    text = value
    try:
        if text.endswith(("Z", "z")):
            text = text[:-1] + "+00:00"
        parsed = datetime.fromisoformat(text)
    except ValueError:
        return None
    if parsed.tzinfo is None:
        # 朴素时间无法判定时区，绝不按本地时间猜测
        return None
    if parsed.utcoffset() != timedelta(0):
        # 只接受 UTC（零偏移），其他时区不做隐式换算

def _parse_round_param(round_param: object) -> int:
    """解析 ?round= 查询参数：须为规范十进制正整数，否则 400。"""
    if (
        not isinstance(round_param, str)
        or not round_param.isascii()
        or not round_param.isdigit()
    ):
        raise ServiceError(400, "round must be a positive integer")
    try:
        round_no = int(round_param)
    except ValueError:
        raise ServiceError(400, "round must be a positive integer")
    if round_no < 1 or str(round_no) != round_param:
        raise ServiceError(400, "round must be a positive integer")
    return round_no

def _resolve_dkg_round(
    self, session: dict | None, round_param: object
) -> int:
    """把 ?round= 参数解析为要操作的轮次号。

    无任何故障轮次时 P 无需参照轮次（行为与旧版一致，显式
    ?round=1 亦接受）；存在故障轮次后必须显式给出当前轮：缺参
    409、旧轮 409、未知轮 404、非法参数 400。"""
    requested = (
        self._parse_round_param(round_param)
        if round_param is not None
        else None
    )
    if session is None:
        # 会话尚不存在：仅 register 可经第 1 轮创建
        if requested is None or requested == 1:
            return 1
        raise ServiceError(404, f"round {requested} not found")
    current = session["current"]
    if requested is None:
        if current > 1:
            raise ServiceError(
                409, "round query parameter is required"
            )
        return 1
    if requested > current:
        raise ServiceError(404, f"round {requested} not found")
    if requested < current:
        raise ServiceError(
            409, f"round {requested} is not the current round"
        )
    return requested

def get_dkg_session(
    self, wallet_id: str, dkg_id: str, round_param: object = None
) -> dict:
    """查询 DKG 会话当前轮视图；钱包/会话未知 404，dkg id 非法 400。

    存在故障轮次后必须带 ?round= 当前轮（缺参/旧轮 409、未知轮
    404、非法 400）；aborted 轮一律 409。"""
    try:
        with self._wallet_lock(wallet_id):
            self._heal_wallet(wallet_id)
            # 404 优先于 400：锁内先判定钱包存在性
            self._get_wallet_or_404(wallet_id)
            self._validate_dkg_id(dkg_id)
            session = self._dkg_sessions(wallet_id).get(dkg_id)
            if session is None:
                raise ServiceError(
                    404, f"dkg session {dkg_id!r} not found"
                )
            round_no = self._resolve_dkg_round(session, round_param)
            if session["rounds"][round_no]["state"] == "aborted":
                raise ServiceError(
                    409,
                    f"dkg session {dkg_id!r} round {round_no} is "
                    "aborted",
                )
            return self._dkg_view(session, round_no)
    except CorruptDataError:
        raise
    except ValueError:
        # wallet_id 含非法字符（构造锁路径时抛出）
        raise ServiceError(400, "invalid wallet_id")

