def _bound_slot_occupied_locked(self, wallet_id: str, slot: int) -> bool:
    """该槽位是否已被仍生效的更早绑定占用（调用方须持钱包锁）。

    更早绑定的份额在以下任一情况仍占槽：份额仍在当前钱包在用集合中
    （绑定已随轮换激活且尚未再轮换出去），或其所属轮换此刻仍处于
    prepared（绑定暂存待激活，尚未被下一轮替换）。"""
    wallet = self._store.get_wallet(wallet_id)
    in_use = (
        {s.get("share_id") for s in wallet.get("shares", [])}
        if isinstance(wallet, dict)
        else set()
    )
    prepared_rotations = {
        record.get("rotation_id")
        for record in self._store.list_rotations(wallet_id)
        if record.get("state") == "prepared"
    }
    for event in self._share_bind_events_strict(wallet_id):
        details = event["details"]
        if details["slot"] != slot:
            continue
        share_id = details["share_id"]
        marker = share_id.rfind("-share-")
        bound_rotation = share_id[:marker] if marker >= 0 else None
        if share_id in in_use or bound_rotation in prepared_rotations:
            return True
    return False

